def dummy_calculate_stock_volatility(prices):
    # Simple dummy volatility calculation: standard deviation of price changes
    if len(prices) < 2:
        return 0.0
    changes = [prices[i+1] - prices[i] for i in range(len(prices)-1)]
    mean = sum(changes) / len(changes)
    var = sum((x - mean)**2 for x in changes) / len(changes)
    return var ** 0.5

